catalog_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below
    var emp = g_form.getValue('employee');
    if (!emp) return;

    var ga = new GlideAjax('x_594089_employe_0.getExitData');
    ga.addParam('sysparm_name', 'getExit');
    ga.addParam('sysparm_employee', emp);
    ga.getXMLAnswer((response) => {
        console.log(response)
        var data = JSON.parse(response);
        if (data.reason != '' && data.other_reason) {
            g_form.setValue('reason', data.reason);
            g_form.setValue('other_reason', data.other_reason);
            g_form.setValue('resignation_date', data.resignation_date);
            g_form.setValue('last_working_day', data.last_working_day);
            g_form.setReadOnly('reason', true);
            g_form.setReadOnly('other_reason', true);
            g_form.setReadOnly('resignation_date', true);
            g_form.setReadOnly('last_working_day', true);
        }
    });
}
